import {drugs,glossary,questions,guides,rhythms,cases,sources} from './content.js';
import {escapeHTML as esc,shuffle,localDate,percent,defaults,sanitizeState,calculate,ecgSVG} from './engine.js';

const $=s=>document.querySelector(s);
let state;try{state=sanitizeState(JSON.parse(localStorage.getItem('pulse-study-v1')||'{}'));}catch{state=defaults();}
let storageWarning=false,toastTimer,returnFocus;
const ui={drugQuery:'',drugCategory:'All',drugSaved:false,ecgId:rhythms[0]?.id,ecgHidden:false,annotations:true,practiceTab:'quiz',quiz:null,match:null,flash:null,caseRun:null,guideQuery:'',glossaryQuery:'',calcType:'volume',calcValues:{},noteQuery:''};
const iconPaths={pulse:'M2 12h5l3-8 4 16 3-8h5',home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 7c-3-3-7-3-10-2v15c4-1 7-1 10 2m0-15c3-3 7-3 10-2v15c-4-1-7-1-10 2V7',pill:'m9 15 6-6M7 3a6 6 0 0 1 8 0l6 6a6 6 0 0 1-8 8l-6-6a6 6 0 0 1 0-8Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',game:'M6 8h12l3 10c.5 3-3 4-5 0l-2-2h-4l-2 2c-2 4-5.5 3-5 0L6 8Zm1 2v5m-2-2h4m7-2h.01m2 3h.01',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3a8 8 0 0 1 16 0v3',chart:'M4 3v18h17M9 17v-5m5 5V7m5 10V4',note:'M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9M9 15l2-5 8-8 3 3-8 8-5 2Z',calc:'M5 2h14v20H5zM8 6h8M8 11h1m5 0h1m-7 4h1m5 0h1m-7 4h1m5 0h1',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',bookmark:'M6 3h12v19l-6-4-6 4Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z',menu:'M4 6h16M4 12h16M4 18h16',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',layers:'m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 12h.01',download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-3 3M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l3-3',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',refresh:'M20 7a9 9 0 1 0 1 9M20 2v6h-6',play:'m8 4 12 8-12 8Z',print:'M6 9V2h12v7M6 18H2V9h20v9h-4M6 14h12v8H6z',heart:'M20 4c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 9 8 16 8-7 12-12 8-16Z',award:'M16 15l2 8-6-3-6 3 2-8M20 9a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
const badge=(text,color='')=>`<span class="badge ${color}">${esc(text)}</span>`;
const list=arr=>`<ul class="bullets">${(arr||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const button=(label,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const navItems=[['desk','Study desk','home'],['drugs','Drug cards','pill'],['ecg','ECG lab','pulse'],['practice','Practice & games','game'],['simulator','Patient simulator','user'],['guides','Study guides','book'],['glossary','Terminology','layers'],['calculators','Dose math','calc'],['notebook','My notebook','note'],['progress','My progress','chart']];
function save(){try{localStorage.setItem('pulse-study-v1',JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Export a backup to keep your progress.');}}}
function markDay(){const d=localDate();if(!state.days.includes(d))state.days.push(d);save();}
function record(type,title,correct,total,category='Mixed'){state.history.push({type,title,correct,total,category,date:new Date().toISOString()});state.history=state.history.slice(-500);markDay();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function route(){const pieces=location.hash.replace(/^#\/?/,'').split('/');return {page:pieces[0]||'desk',id:pieces[1]||''};}
function go(path){if(location.hash===`#/${path}`)render();else location.hash=`#/${path}`;}
function refs(ids=[]){return `<div class="source-links">${[...new Set(ids)].map(id=>sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.organization||s.title)} ${icon('link',12)}</a>`).join('')}</div>`;}
function saveButton(key){const yes=state.bookmarks.includes(key);return `<button class="save-btn ${yes?'saved':''}" data-action="bookmark" data-key="${esc(key)}" aria-label="${yes?'Remove bookmark':'Bookmark'}" aria-pressed="${yes}">${icon('bookmark',19)}</button>`;}
function openModal(title,body,sub=''){returnFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><div>${sub?`<div class="eyebrow">${esc(sub)}</div>`:''}<h2 id="modal-title">${esc(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();}
$('#modal').addEventListener('close',()=>{returnFocus?.isConnected&&returnFocus.focus();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const heads={desk:['Study desk','A little practice. A more confident clinician.'],drugs:['Drug cards','Indications, doses, precautions, and the details that matter.'],ecg:['ECG lab','Read the rhythm. Connect it to the patient.'],practice:['Practice & games','Build recall with questions, matching, and flashcards.'],simulator:['Patient simulator','Work through the call, one decision at a time.'],guides:['Study guides','Focused references across the paramedic curriculum.'],glossary:['Terminology','Plain-language definitions for the words you need to know.'],calculators:['Dose math','Practice the calculation and follow every unit.'],notebook:['My notebook','Your saved references and study notes, in one place.'],progress:['My progress','See what you have practiced and what to revisit.'],sources:['Sources & scope','Clinical references and how to use this study collection.']};
function pageHead(page){const [title,desc]=heads[page]||['Page not found','Choose a study tool from the navigation.'];return `<div class="page-head"><div><h1 tabindex="-1">${title}</h1><p>${desc}</p></div><div class="head-actions">${page==='desk'?`<span class="small date">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span>${button(`${icon('play',15)} Quick practice`,'quick-quiz','primary')}`:page==='notebook'?button(`${icon('note',16)} New note`,'new-note','primary'):page==='progress'?button(`${icon('download',16)} Export progress`,'export','ghost'):''}</div></div>`;}
function render(){const oldFocus=document.activeElement;const focusAction=oldFocus?.dataset?.action;const focusId=oldFocus?.dataset?.id;const focusIndex=oldFocus?.dataset?.index;const {page,id}=route();document.title=`${heads[page]?.[0]||'Study'} · Pulse`;document.documentElement.dataset.theme=state.theme;
 const content={desk:dashboard,drugs:drugView,ecg:ecgView,practice:practiceView,simulator:simulatorView,guides:()=>guideView(id),glossary:glossaryView,calculators:calculatorView,notebook:notebookView,progress:progressView,sources:sourcesView}[page];
 $('#app').innerHTML=`<div class="mobile-shade" data-action="menu-close"></div><aside class="sidebar" aria-label="Study navigation"><a class="brand" href="#/desk"><span class="brand-mark">${icon('pulse',29)}</span><div><div class="brand-name">pulse<span class="mint">.</span></div><small>Paramedic study</small></div></a><div class="eyebrow" style="padding:0 14px 8px">Your workspace</div><nav>${navItems.map(([key,label,i],n)=>`${n===8?'<div class="nav-group">Your learning</div>':''}<a class="nav-link ${page===key?'active':''}" href="#/${key}" ${page===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-foot"><a class="link-button muted" href="#/sources">${icon('info',15)} Sources & study scope</a><p>Educational practice<br>Follow your local clinical protocols</p><div class="profile"><span class="avatar">${esc((state.name||'P')[0].toUpperCase())}</span><div><div style="font-size:.8125rem">${esc(state.name||'Your study space')}</div><small>Saved on this device</small></div><button class="icon-btn" style="margin-left:auto;border:0" data-action="settings" aria-label="Study settings">${icon('user',16)}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="flex"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span><span class="crumb-chevron">${icon('chevron',13)}</span><b>${esc(heads[page]?.[0]||'Study')}</b></div></div><div class="top-actions"><button class="search-launch" data-action="search" aria-label="Search all study content">${icon('search',17)} Search your study space <kbd>Ctrl K</kbd></button><button class="icon-btn" data-action="theme" aria-label="Switch to ${state.theme==='dark'?'light':'dark'} theme">${icon(state.theme==='dark'?'sun':'moon',18)}</button></div></header><main id="main" class="main" tabindex="-1">${pageHead(page)}${content?content():empty('That page is not here.','Open the study desk to continue.','desk')}<footer class="footer"><span>Pulse · Paramedic study <span aria-hidden="true">/</span> v1.0.0</span><span>Study use only · <a href="#/sources">Sources & limitations</a> · Device-local progress</span></footer></main></div>`;
 if(page==='calculators')updateCalc();
 if(focusAction&&!$('#modal').open){const same=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===focusAction&&x.dataset.id===focusId&&x.dataset.index===focusIndex&&!x.disabled);const focus=same||$('.feedback .button')||$('.question');if(focus){if(!focus.hasAttribute('tabindex')&&!['BUTTON','A'].includes(focus.tagName))focus.setAttribute('tabindex','-1');focus.focus({preventScroll:true});}}
}
function empty(title,desc,path){return `<div class="panel empty"><h2>${esc(title)}</h2><p>${esc(desc)}</p>${path?`<a class="button" href="#/${path}">Open study desk</a>`:''}</div>`;}
function streak(){const days=new Set(state.days);const d=new Date();if(!days.has(localDate(d)))d.setDate(d.getDate()-1);let n=0;while(days.has(localDate(d))){n++;d.setDate(d.getDate()-1);}return n;}
function totals(){return state.history.filter(h=>['quiz','terminology','simulator'].includes(h.type)).reduce((a,h)=>({correct:a.correct+h.correct,total:a.total+h.total}),{correct:0,total:0});}
function statsHTML(items){return `<div class="stats">${items.map(([value,label,i])=>`<div class="panel stat"><span class="stat-icon">${icon(i,21)}</span><div><div class="stat-number">${esc(value)}</div><div class="stat-label">${esc(label)}</div></div></div>`).join('')}</div>`;}
function dashboard(){const t=totals();const today=state.history.filter(h=>localDate(new Date(h.date))===localDate());const answered=today.reduce((sum,h)=>sum+h.total,0);const dailyPool=rhythms.filter(r=>r.shape!=='pea');const challenge=dailyPool[Math.floor(Date.parse(localDate()+'T00:00:00Z')/86400000)%dailyPool.length];const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;});
 const tools=[['drugs','Drug cards',`${drugs.length} medication cards, with doses and clinical pearls.`,`${drugs.length} cards`,'pill','mint'],['ecg','ECG lab','Learn the patterns. Test your rhythm recognition.',`${rhythms.length} rhythm lessons`,'pulse','blue'],['practice','Practice & games','Turn terminology and clinical knowledge into recall.','4 ways to practice','game','lavender'],['simulator','Patient simulator','Assess, make a decision, and reassess your patient.',`${cases.length} clinical scenarios`,'user','rose']];
 return `${statsHTML([[`${streak()} ${streak()===1?'day':'days'}`,'Study streak','clock'],[state.history.length,'Sessions completed','check'],[t.total?percent(t.correct,t.total)+'%':'—','First-attempt accuracy','target'],[state.bookmarks.length,'Saved references','bookmark']])}<div class="dashboard-grid"><div class="stack"><section class="panel focus-panel"><div class="focus-top"><span class="eyebrow mint">Today’s practice</span>${badge('10 questions','mint')}</div><h2>Keep your clinical thinking sharp.</h2><p>A mixed set of assessment, pharmacology, and patient care questions. Review the reasoning after every answer.</p><div class="focus-bottom">${button(`Start a practice session ${icon('arrow',17)}`,'quick-quiz','primary')}<small>${icon('clock',14)} About 5–10 minutes · Untimed</small></div></section><section><div class="section-title"><h2>Your study tools</h2><span class="small">Learn. Practice. Repeat.</span></div><div class="tool-grid">${tools.map(([path,title,desc,meta,i,color])=>`<a class="panel tool-card" href="#/${path}"><div class="tool-top"><span class="tool-icon ${color}" style="background:var(--${color}-bg)">${icon(i,23)}</span>${icon('arrow',17)}</div><h3>${title}</h3><p>${desc}</p><div class="tool-meta">${meta}</div></a>`).join('')}</div></section><section class="panel panel-pad"><div class="panel-head"><h2>Keep exploring</h2><a class="link-button" href="#/guides">All study guides ${icon('arrow',14)}</a></div><div class="grid two">${guides.slice(0,2).map(g=>`<a class="concept-card" style="padding:0" href="#/guides/${g.id}"><div class="eyebrow">${esc(g.category)}</div><h3 style="margin-top:9px">${esc(g.title)}</h3><p>${esc(g.summary)}</p></a>`).join('')}</div></section></div><div class="stack"><section class="panel rhythm-mini"><div class="panel-head"><h2>Rhythm of the day</h2>${badge('ECG lab','blue')}</div><div class="ecg-wrap">${ecgSVG(challenge?.shape,challenge?.bpm,{compact:true})}</div><h3>What do you see?</h3><p style="font-size:.875rem;margin-top:8px">Start with rate and regularity. Then look for P waves and measure the QRS.</p><button class="link-button spaced" data-action="rhythm-challenge" data-id="${challenge?.id}">Study this rhythm ${icon('arrow',15)}</button></section><section class="panel panel-pad"><div class="panel-head"><h2>Your daily goal</h2><span class="small">${Math.min(answered,state.goal)} / ${state.goal}</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,percent(answered,state.goal))}%"></div></div>${[['Complete a practice session','quiz','10 focused questions'],['Review a flashcard set','flashcards','Terms or medications'],['Work through a patient call','simulator','Decisions with feedback']].map(([title,type,desc])=>`<div class="task-row"><span class="check-ring ${today.some(h=>h.type===type)?'done':''}">${today.some(h=>h.type===type)?icon('check',13):''}</span><div class="task-copy"><b>${title}</b><small>${desc}</small></div></div>`).join('')}<div class="weekly">${days.map(d=>`<div class="day"><span class="${state.days.includes(localDate(d))?'studied':''}">${state.days.includes(localDate(d))?icon('check',12):d.getDate()}</span>${d.toLocaleDateString(undefined,{weekday:'narrow'})}</div>`).join('')}</div></section><section class="panel panel-pad"><div class="eyebrow gold">Study note</div><h3 style="margin:12px 0 8px">Treat the patient, not the monitor.</h3><p style="font-size:.875rem">An organized rhythm does not confirm a pulse. Pair electrical activity with a clinical assessment.</p><a class="link-button spaced" href="#/guides">Review assessment ${icon('arrow',14)}</a></section></div></div>`;
}

function drugView(){return `<div class="toolbar"><label class="search-field">${icon('search',18)}<input id="drug-search" aria-label="Search medications" placeholder="Search a drug, indication, or trade name…" value="${esc(ui.drugQuery)}"></label><select id="drug-category" aria-label="Filter medication category"><option>All</option>${[...new Set(drugs.map(d=>d.category))].sort().map(c=>`<option ${ui.drugCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="button ghost" data-action="drug-saved" aria-pressed="${ui.drugSaved}">${icon('bookmark',16)} ${ui.drugSaved?'Showing saved':'Saved only'}</button><button class="button" data-action="drug-flash">${icon('layers',16)} Flashcards</button></div><div class="notice subtle">Doses are labeled by indication and route. Local protocols, formulation, and patient factors determine actual care.</div><div id="drug-results">${drugResults()}</div>`;}
function drugResults(){const q=ui.drugQuery.toLowerCase();const filtered=drugs.filter(d=>(ui.drugCategory==='All'||d.category===ui.drugCategory)&&(!ui.drugSaved||state.bookmarks.includes('drug:'+d.id))&&[d.name,...d.aliases,...d.indications].join(' ').toLowerCase().includes(q));return `<div class="count-label">${filtered.length} medications</div>${filtered.length?`<div class="drug-grid">${filtered.map((d,i)=>`<article class="panel drug-card"><div class="card-top">${badge(d.category,['mint','blue','lavender','rose','gold'][i%5])}${saveButton('drug:'+d.id)}</div><h2>${esc(d.name)}</h2><p class="aliases">${esc(d.aliases.join(' · '))}</p><p>${esc(d.indications.slice(0,2).join(' · '))}</p><div class="card-bottom"><button class="link-button" data-action="drug" data-id="${d.id}">Open drug card ${icon('arrow',15)}</button><span class="small">${d.adultDose.length} dose ${d.adultDose.length===1?'entry':'entries'}</span></div></article>`).join('')}</div>`:empty('No matching medications.','Try a different term or remove the saved-only filter.')}`;}
function drugModal(id){const d=drugs.find(x=>x.id===id);if(!d)return;openModal(d.name,`${badge(d.category,'mint')}<p class="spaced">${esc(d.mechanism)}</p><div class="detail-section"><h3>Indications</h3>${list(d.indications)}</div><div class="detail-section"><h3>Adult dosing</h3><div class="table-wrap"><table><thead><tr><th>Indication</th><th>Dose & administration</th><th>Route</th></tr></thead><tbody>${d.adultDose.map(x=>`<tr><td>${esc(x.use)}</td><td>${esc(x.dose)}</td><td>${esc(x.route)}</td></tr>`).join('')}</tbody></table></div></div><div class="detail-section"><h3>Pediatric considerations</h3><p>${esc(d.pediatricDose)}</p></div><div class="grid two detail-section"><div><h3>Contraindications & cautions</h3>${list(d.contraindications)}</div><div><h3>Adverse effects</h3>${list(d.adverseEffects)}</div></div><div class="detail-section"><h3>Monitor & reassess</h3>${list(d.monitoring)}</div><div class="detail-section"><h3>Clinical pearls</h3>${list(d.pearls)}</div><div class="detail-section"><h3>Sources</h3><small>Accessed September 15, 2026 · Verify with your current local formulary.</small>${refs(d.sourceIds)}</div><div class="detail-controls">${button(`${icon('bookmark',16)} ${state.bookmarks.includes('drug:'+id)?'Bookmarked':'Bookmark'}`,'bookmark','',`data-key="drug:${id}"`)}${button(`${icon('note',16)} Add study note`,'edit-note','',`data-key="drug:${id}" data-title="${esc(d.name)}"`)}${button(`${icon('print',16)} Print card`,'print')}</div>`,d.aliases.join(' · '));}

function ecgView(){const r=rhythms.find(x=>x.id===ui.ecgId)||rhythms[0];if(!r)return '';return `<div class="ecg-layout"><nav class="panel rhythm-list" aria-label="Rhythm examples">${ui.ecgHidden?'<p class="small" style="padding:14px">Rhythm selection is hidden for this challenge. Reveal the explanation to browse lessons.</p>':rhythms.map(x=>`<button class="rhythm-select ${r.id===x.id?'active':''}" data-action="rhythm" data-id="${x.id}" aria-pressed="${r.id===x.id}">${esc(x.name)}</button>`).join('')}</nav><section class="panel panel-pad rhythm-study"><div class="ecg-topline"><div><div class="eyebrow">6-second rhythm study</div><h2 style="margin-top:8px">${ui.ecgHidden?'Identify this rhythm':esc(r.name)}</h2></div>${ui.ecgHidden?'':saveButton('rhythm:'+r.id)}</div><div class="ecg-wrap">${ecgSVG(r.shape,r.bpm,{annotations:ui.annotations&&!ui.ecgHidden,irregular:r.name.toLowerCase().includes('sinus arrhythmia')}).replace(/aria-label="[^"]*"/,`aria-label="${ui.ecgHidden?'Practice rhythm strip. Identify the illustrated pattern.':esc(r.name)+' schematic rhythm. See the written interpretation below.'}"`)}<div class="ecg-strip-label"><span>Schematic lead II · 25 mm/s time scale</span><span>6 seconds</span></div></div><div class="ecg-description">Illustrated teaching pattern, not a patient recording. Intervals and morphology are simplified. Zooming changes displayed size.</div><div class="ecg-options"><label class="toggle"><input id="ecg-annotations" type="checkbox" ${ui.annotations?'checked':''}> Label P, QRS & T where applicable</label>${button(ui.ecgHidden?'Reveal explanation':'Hide explanation','ecg-hide','small ghost')}${button(`${icon('play',14)} Rhythm quiz`,'ecg-quiz','small')}</div>${ui.ecgHidden?`<div class="notice subtle spaced">Assess rate, regularity, P waves, PR interval, and QRS width. Consider what else you need to know about the patient.</div>`:`<div class="rhythm-stats">${[['Rate',r.rate],['Regularity',r.regularity],['P waves',r.pWaves],['PR interval',r.pr],['QRS',r.qrs],['Teaching rate',['vf','asystole'].includes(r.shape)?'No organized rate':`${r.bpm} bpm${['mobitz1','mobitz2'].includes(r.shape)?' (average)':''}`]].map(([title,v])=>`<div class="definition"><small>${title}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="ecg-answer"><p>${esc(r.explanation)}</p><div class="grid two detail-section"><div><h3>Recognition clues</h3>${list(r.clues)}</div><div><h3>Clinical priorities</h3>${list(r.priorities)}</div></div><div class="notice spaced"><strong>Common pitfall</strong><p style="margin-top:5px">${esc(r.pitfall)}</p></div>${refs(r.sourceIds)}</div>`}</section></div>`;}

function practiceView(){const tabs=[['quiz','Clinical questions'],['terminology','Terminology sprint'],['matching','Match pairs'],['flashcards','Flashcards']];return `<div class="tabs" aria-label="Practice modes">${tabs.map(([key,title])=>`<button class="tab ${ui.practiceTab===key?'active':''}" data-action="practice-tab" data-tab="${key}" aria-pressed="${ui.practiceTab===key}">${title}</button>`).join('')}</div>${ui.quiz?quizView():ui.match?matchView():ui.flash?flashView():practiceSetup()}`;}
function practiceSetup(){const mode=ui.practiceTab;const title={quiz:'Think through the clinical question.',terminology:'Make medical language second nature.',matching:'Find the connection.',flashcards:'Build recall, one card at a time.'}[mode];const desc={quiz:`${questions.length} questions across key clinical topics. Explanations follow every answer, with a review at the end.`,terminology:`Practice ${glossary.length} terms with short definition questions. Accuracy comes first; there is no timer.`,matching:'Match six medical terms to their definitions. Select a term, then its meaning. Keep going until every pair is connected.',flashcards:'Review terminology or drug indications. Rate your recall to schedule the next review on this device.'}[mode];return `<section class="panel panel-pad practice-setup"><div class="mode-icon">${icon(mode==='matching'?'grid':mode==='flashcards'?'layers':'target',28)}</div><h2>${title}</h2><p>${desc}</p><div class="form-row">${mode==='quiz'?`<label><span class="form-label">Topic</span><select id="quiz-category"><option>Mixed</option>${[...new Set(questions.map(q=>q.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label>`:mode==='flashcards'?`<label><span class="form-label">Card collection</span><select id="flash-deck"><option value="terms">Terminology</option><option value="drugs">Medication indications</option><option value="saved">Saved medications</option></select></label><label><span class="form-label">Review mode</span><select id="flash-filter"><option value="due">Due for review</option><option value="all">All cards</option></select></label>`:''}${mode==='quiz'||mode==='terminology'?`<label><span class="form-label">Session length</span><select id="quiz-count"><option>10</option><option>5</option><option>20</option></select></label>`:''}${button(`Start ${mode==='matching'?'matching':mode==='flashcards'?'review':'practice'} ${icon('arrow',16)}`,'start-practice','primary')}</div></section>`;}
function newQuiz(mode='quiz',category='Mixed',count=10){let pool;if(mode==='terminology'){pool=shuffle(glossary).map(g=>{const opts=shuffle([g,...shuffle(glossary.filter(x=>x.id!==g.id)).slice(0,3)]);return {id:g.id,category:g.category,question:`What does “${g.term}” mean?`,options:opts.map(x=>x.definition),answer:opts.findIndex(x=>x.id===g.id),explanation:g.definition,sourceIds:g.sourceIds};});}else if(mode==='ecg'){pool=shuffle(rhythms.filter(r=>r.shape!=='pea')).map(r=>{const opts=shuffle([r,...shuffle(rhythms.filter(x=>x.id!==r.id&&x.shape!=='pea')).slice(0,3)]);return {id:r.id,category:'ECG recognition',question:'Which rhythm best matches this illustrated pattern?',options:opts.map(x=>x.name),answer:opts.findIndex(x=>x.id===r.id),explanation:`${r.explanation} ${r.pitfall}`,sourceIds:r.sourceIds,strip:r};});}else pool=shuffle(questions.filter(q=>category==='Mixed'||q.category===category));
 pool=pool.map(q=>{const options=shuffle(q.options.map((text,index)=>({text,index})));return {...q,options:options.map(o=>o.text),answer:options.findIndex(o=>o.index===q.answer)};});
 ui.quiz={mode,category,items:pool.slice(0,count),index:0,selected:null,responses:[],finished:false};ui.practiceTab=mode==='terminology'?'terminology':'quiz';ui.match=null;ui.flash=null;go('practice');}
function quizView(){const q=ui.quiz;if(!q.items.length)return empty('No questions for this topic.','Select a different topic.');if(q.finished)return quizResults(q);const item=q.items[q.index];return `<section class="panel panel-pad quiz-box"><div class="quiz-header"><span>${q.mode==='ecg'?'ECG recognition':esc(item.category)} · Question ${q.index+1} of ${q.items.length}</span>${button('End session','end-practice','small ghost')}</div><div class="progress-track"><div class="progress-fill" style="width:${percent(q.index,q.items.length)}%"></div></div>${item.strip?`<div class="ecg-wrap spaced">${ecgSVG(item.strip.shape,item.strip.bpm,{irregular:item.strip.name.toLowerCase().includes('sinus arrhythmia')}).replace(/aria-label="[^"]*"/,'aria-label="Practice rhythm strip. Identify the illustrated pattern."')}</div><div class="ecg-description">Schematic rhythm · 6 seconds · Teaching example</div>`:''}<h2 class="question">${esc(item.question)}</h2><div class="answers">${item.options.map((o,i)=>`<button class="answer ${q.selected!==null?(i===item.answer?'correct':i===q.selected?'incorrect':''):''}" data-action="quiz-answer" data-index="${i}" ${q.selected!==null?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>${q.selected!==null?`<div class="feedback ${q.selected!==item.answer?'wrong':''}" role="status"><strong>${q.selected===item.answer?'Correct.':'Let’s review that.'}</strong><p>${esc(item.explanation)}</p>${refs(item.sourceIds)}${button(q.index+1===q.items.length?'See session review':'Next question','quiz-next','primary')}</div>`:''}</section>`;}
function quizResults(q){const correct=q.responses.filter(x=>x.correct).length;return `<section class="panel panel-pad quiz-box"><div class="results"><div class="score-circle"><strong>${percent(correct,q.items.length)}%</strong><small>${correct} of ${q.items.length} correct</small></div><h2>Session complete.</h2><p>${correct===q.items.length?'Strong work. Try a different topic to broaden your practice.':'Review the reasoning below, then revisit the questions you missed.'}</p><div class="flex wrap" style="justify-content:center;margin-bottom:25px">${button(`${icon('refresh',16)} New session`,'end-practice','primary')}${correct<q.items.length?button('Retry missed questions','retry-missed'):''}<a class="button ghost" href="#/progress">View progress</a></div></div>${q.responses.map((r,i)=>`<div class="review-row"><div class="flex">${badge(r.correct?'Correct':'Review',r.correct?'mint':'rose')}<strong>${esc(q.items[i].question)}</strong></div><p>Your answer: ${esc(q.items[i].options[r.selected])}</p>${!r.correct?`<p class="mint">Correct answer: ${esc(q.items[i].options[q.items[i].answer])}</p>`:''}<p>${esc(q.items[i].explanation)}</p></div>`).join('')}</section>`;}
function startMatch(){const items=shuffle(glossary).slice(0,6);ui.match={items,right:shuffle(items),selected:null,matched:[],attempts:0,wrong:null,completed:false};ui.quiz=null;ui.flash=null;render();}
function matchView(){const m=ui.match;return `<section class="panel panel-pad quiz-box"><div class="quiz-header"><span>${m.matched.length} of 6 pairs matched · ${m.attempts} attempts</span>${button('New pairs','new-match','small ghost')}</div><h2 style="margin-top:20px">Match each term to its meaning.</h2><p class="spaced" style="font-size:.875rem">Select a term on the left, then a definition on the right.</p><div class="matching-grid"><div class="match-column">${m.items.map(g=>`<button class="match-item ${m.selected===g.id?'selected':''} ${m.matched.includes(g.id)?'matched':''}" data-action="match-left" data-id="${g.id}" ${m.matched.includes(g.id)?'disabled':''} aria-pressed="${m.selected===g.id}">${esc(g.term)} ${m.matched.includes(g.id)?icon('check',16):''}</button>`).join('')}</div><div class="match-column">${m.right.map(g=>`<button class="match-item ${m.matched.includes(g.id)?'matched':''} ${m.wrong===g.id?'wrong':''}" data-action="match-right" data-id="${g.id}" ${m.matched.includes(g.id)?'disabled':''}>${esc(g.definition)}</button>`).join('')}</div></div>${m.completed?`<div class="feedback"><strong>All six pairs connected.</strong><p>${m.attempts===6?'A perfect round.':`You completed the round in ${m.attempts} attempts. Review unfamiliar terms in the terminology reference.`}</p>${button('Play another round','new-match','primary')}</div>`:''}</section>`;}
function flashPool(deck){if(deck==='terms')return glossary.map(g=>({id:'term:'+g.id,front:g.term,back:g.definition,category:g.category}));return drugs.filter(d=>deck!=='saved'||state.bookmarks.includes('drug:'+d.id)).map(d=>({id:'drug:'+d.id,front:d.name,back:d.indications.join(' · '),category:'Recall the indications'}));}
function startFlash(deck='terms',filter='due'){let pool=flashPool(deck);if(filter==='due')pool=pool.filter(c=>!state.reviews[c.id]||state.reviews[c.id].due<=Date.now());ui.flash={items:shuffle(pool).slice(0,10),index:0,revealed:false,ratings:[],deck,finished:false};ui.quiz=null;ui.match=null;ui.practiceTab='flashcards';go('practice');}
function flashView(){const f=ui.flash;if(!f.items.length)return `<section class="panel empty"><h2>${f.deck==='saved'?'No saved medication cards are due.':'You’re caught up on this collection.'}</h2><p>Review all cards or choose another collection.</p>${button('Choose a collection','end-practice','primary')}</section>`;if(f.finished)return `<section class="panel panel-pad quiz-box results"><div class="score-circle"><strong>${f.items.length}</strong><small>cards reviewed</small></div><h2>A little more knowledge, retained.</h2><p>Cards rated Again are due in your next review session. Good returns in at least 1 day. Easy returns in at least 4 days.</p>${button('Choose another collection','end-practice','primary')}</section>`;const c=f.items[f.index];return `<section class="quiz-box"><div class="quiz-header"><span>${f.index+1} / ${f.items.length} cards · ${esc(c.category)}</span>${button('End review','end-practice','small ghost')}</div><button class="flashcard" data-action="flash-flip" aria-label="${f.revealed?'Show question':'Reveal answer'}"><span class="eyebrow">${f.revealed?'Answer':'Recall'}</span><span class="${f.revealed?'back':'front'}">${esc(f.revealed?c.back:c.front)}</span><small>${icon('refresh',13)} Click or press Space to flip</small></button>${f.revealed?`<div class="flash-controls">${button('Again · now','flash-rate','danger', 'data-rating="again"')}${button('Good · 1+ day','flash-rate','', 'data-rating="good"')}${button('Easy · 4+ days','flash-rate','primary', 'data-rating="easy"')}</div>`:'<p class="center small spaced">Think of your answer before revealing the card.</p>'}</section>`;}

function simulatorView(){if(ui.caseRun)return caseView();return `<div class="notice subtle">Scripted training scenarios with decision-based vital changes. These are learning exercises, not validated physiologic predictions or live treatment guidance.</div><div class="sim-grid">${cases.map((c,i)=>`<article class="panel case-card"><div class="card-top">${badge(c.category,['mint','blue','rose','lavender'][i%4])}${badge(c.difficulty)}</div><h2>${esc(c.title)}</h2><p>${esc(c.dispatch)}</p><div class="flex spread" style="margin-bottom:20px"><small>${c.steps.length} decision stages</small><small>${state.history.some(h=>h.type==='simulator'&&h.title===c.title)?'Previously completed':'Not yet completed'}</small></div>${button(`Start scenario ${icon('arrow',16)}`,'start-case','',`data-id="${c.id}"`)}</article>`).join('')}</div>`;}
function startCase(id){const source=cases.find(x=>x.id===id);if(!source)return;const c={...source,steps:source.steps.map(s=>({...s,options:shuffle(s.options)}))};const initial={...c.initial,...c.steps[0].onEnter};ui.caseRun={case:c,index:0,vitals:initial,baseline:{...initial},selected:null,attempts:0,score:0,log:[],finished:false};render();}
function caseView(){const r=ui.caseRun,c=r.case,v=r.vitals,step=c.steps[r.index];if(r.finished)return `<section class="panel panel-pad quiz-box"><div class="results"><div class="score-circle"><strong>${r.score}/${c.steps.length}</strong><small>first-choice decisions</small></div><h2>${esc(c.title)}: debrief</h2><p>Review the priorities you used and the decisions you would change.</p></div><div class="detail-section"><h3>Key takeaways</h3>${list(c.debrief)}</div><div class="detail-section"><h3>Your decision log</h3>${caseLog(r)}</div>${refs(c.sourceIds)}<div class="detail-controls">${button('Choose another case','leave-case','primary')}${button('Repeat this case','start-case','',`data-id="${c.id}"`)}</div></section>`;
 const rhythm=rhythms.find(x=>x.id===v.rhythm||x.name.toLowerCase()===String(v.rhythm).toLowerCase()||x.shape===v.rhythm);return `<div class="flex spread wrap" style="margin-bottom:22px"><div class="flex wrap">${badge(c.category,'mint')}<h2>${esc(c.title)}</h2></div>${button('Leave scenario','confirm-leave','small ghost')}</div><div class="simulator-layout"><div class="stack"><section class="monitor"><div class="flex spread"><span class="eyebrow" style="color:#bad6c5">Patient monitor</span><span class="small" style="color:#b8c6c1">Simulation</span></div><div class="ecg-wrap">${ecgSVG(v.rhythm==='paced'?'paced':rhythm?.shape||'sinus',v.hr||0,{compact:true})}</div><div class="vitals">${[['HR',['vf','asystole'].includes(v.rhythm)?null:v.hr,'bpm'],['SpO₂',v.spo2,'%'],['NIBP',v.sbp>0?`${v.sbp}/${v.dbp}`:null,'mmHg'],['Respirations',v.rr,'/min'],['ETCO₂',v.etco2,'mmHg'],['GCS',v.gcs,'/15'],['Glucose',v.glucose,'mg/dL'],['Temperature',v.temp,'°C']].map(([name,val,unit])=>`<div class="vital"><small>${name}</small><strong>${val===null||val===undefined?'—':esc(val)}</strong><span>${unit}</span></div>`).join('')}</div><p style="font-size:.75rem;color:#b8c6c1;margin-top:13px">Vitals change after decisions. Scenario time is paused between actions.</p></section><section class="panel panel-pad patient-brief"><h3>Patient information</h3><p style="margin-top:10px">${esc(c.patient.age)} years · ${esc(c.patient.sex)} · ${esc(c.patient.complaint)}</p><dl>${[['History',c.patient.history],['Medication',c.patient.medications],['Allergies',c.patient.allergies]].map(([k,val])=>`<dt>${k}</dt><dd>${esc(Array.isArray(val)?val.join(', '):val)}</dd>`).join('')}</dl></section></div><div class="stack"><section class="panel panel-pad"><div class="quiz-header"><span>Decision ${r.index+1} of ${c.steps.length}</span>${badge('Assess → Act → Reassess','blue')}</div><div class="progress-track"><div class="progress-fill" style="width:${percent(r.index,c.steps.length)}%"></div></div><h2 class="question">${esc(step.prompt)}</h2><div class="answers">${step.options.map((o,i)=>`<button class="answer ${r.selected===i?(o.correct?'correct':'incorrect'):''}" data-action="case-answer" data-index="${i}" ${r.selected!==null?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o.label)}</span></button>`).join('')}</div>${r.selected!==null?`<div class="feedback ${step.options[r.selected].correct?'':'wrong'}" role="status"><strong>${step.options[r.selected].correct?'Appropriate next step.':'Reassess your approach.'}</strong><p>${esc(step.options[r.selected].explanation)}</p>${button(step.options[r.selected].correct?(r.index+1===c.steps.length?'Complete & debrief':'Continue assessment'):'Try another action',step.options[r.selected].correct?'case-next':'case-retry','primary')}</div>`:''}</section>${r.log.length?`<section class="panel panel-pad"><div class="panel-head"><h2>Decision log</h2></div>${caseLog(r)}</section>`:''}</div></div>`;}
function caseLog(r){return `<div class="event-log">${r.log.map(l=>`<div><span class="small">Stage ${l.stage} · ${l.correct?'Appropriate':'Reassess'}</span><p>${esc(l.label)}</p></div>`).join('')}</div>`;}

function guideView(id){if(id){const g=guides.find(x=>x.id===id);if(!g)return empty('Guide not found.','Choose another guide.');return `<article class="panel panel-pad guide-detail"><div class="flex spread wrap"><a class="link-button" href="#/guides">All study guides</a>${saveButton('guide:'+g.id)}</div><div style="margin:24px 0"><div class="eyebrow">${esc(g.category)}</div><h2 style="font-size:1.7rem;margin-top:10px">${esc(g.title)}</h2><p>${esc(g.summary)}</p></div>${g.sections.map(s=>`<section class="guide-section"><h2>${esc(s.title)}</h2>${list(s.points)}</section>`).join('')}<div class="detail-section"><h3>Sources & further reading</h3>${refs(g.sourceIds)}</div><div class="detail-controls">${button(`${icon('note',16)} Add study note`,'edit-note','',`data-key="guide:${g.id}" data-title="${esc(g.title)}"`)}${button(`${icon('print',16)} Print guide`,'print')}</div></article>`;}return `<div class="toolbar"><label class="search-field">${icon('search',18)}<input id="guide-search" aria-label="Search study guides" placeholder="Search topics, systems, or assessment…" value="${esc(ui.guideQuery)}"></label></div><div id="guide-results">${guideResults()}</div>`;}
function guideResults(){const q=ui.guideQuery.toLowerCase();const items=guides.filter(g=>JSON.stringify(g).toLowerCase().includes(q));return items.length?`<div class="grid three">${items.map((g,i)=>`<a class="panel guide-card" href="#/guides/${g.id}">${badge(g.category,['mint','blue','lavender','rose','gold'][i%5])}<h2>${esc(g.title)}</h2><p>${esc(g.summary)}</p><small>${g.sections.length} focused sections ${icon('arrow',14)}</small></a>`).join('')}</div>`:empty('No matching study guides.','Try a broader topic.');}
function glossaryView(){return `<div class="toolbar"><label class="search-field">${icon('search',18)}<input id="glossary-search" aria-label="Search terminology" placeholder="Search a term or definition…" value="${esc(ui.glossaryQuery)}"></label>${button(`${icon('game',16)} Practice terms`,'term-practice','primary')}</div><section class="panel panel-pad" id="glossary-results">${glossaryResults()}</section>`;}
function glossaryResults(){const q=ui.glossaryQuery.toLowerCase();const items=glossary.filter(g=>(g.term+' '+g.definition+' '+g.category).toLowerCase().includes(q)).sort((a,b)=>a.term.localeCompare(b.term));return `<div class="count-label">${items.length} terms</div>${items.map(g=>`<div class="glossary-row"><div><strong>${esc(g.term)}</strong><small style="display:block;margin-top:4px">${esc(g.category)}</small></div><div><p>${esc(g.definition)}</p></div></div>`).join('')||'<p>No matching terms. Try a broader search.</p>'}`;}

const calcConfigs={volume:{name:'Dose to volume',fields:[['dose','Desired dose','1'],['available','Drug amount available','2'],['volume','Volume containing that amount (mL)','1']],unit:true,description:'Desired dose and available drug must use the same unit. Volume is the amount to draw up.'},weight:{name:'Weight-based dose',fields:[['weight','Patient weight (kg)','70'],['perkg','Ordered dose per kg','0.1'],['concentration','Concentration per mL','1']],unit:true,description:'Confirm the protocol maximum dose before using a weight-based result. This exercise does not apply a maximum.'},infusion:{name:'Infusion rate',fields:[['weight','Patient weight (kg)','70'],['dose','Ordered dose (mcg/kg/min)','0.05'],['drug','Drug amount in bag','4'],['bag','Total bag volume (mL)','250']],description:'Convert the drug amount to micrograms before dividing by the total bag volume.'},drip:{name:'Gravity drip',fields:[['volume','Fluid volume (mL)','250'],['minutes','Infusion time (minutes)','30'],['factor','Drop factor (gtt/mL)','15']],description:'Use the drop factor printed on the administration set. Gravity rates are rounded to a whole drop.'},map:{name:'Mean arterial pressure',fields:[['sbp','Systolic pressure (mmHg)','120'],['dbp','Diastolic pressure (mmHg)','80']],description:'Approximation using SBP and DBP. It is less reliable with marked tachycardia, arrhythmia, or unusual pulse waveforms.'}};
function calcDefaults(type){return Object.fromEntries([...calcConfigs[type].fields.map(([key,,value])=>[key,value]),['unit','mg'],['drugUnit','mg']]);}
function calculatorView(){const c=calcConfigs[ui.calcType];if(!Object.keys(ui.calcValues).length)ui.calcValues=calcDefaults(ui.calcType);return `<div class="notice">Practice calculator only. Results do not validate an indication, concentration, route, dose limit, or clinical order.</div><div class="chips">${Object.entries(calcConfigs).map(([key,val])=>`<button class="chip ${key===ui.calcType?'active':''}" data-action="calc-type" data-type="${key}">${val.name}</button>`).join('')}</div><section class="panel panel-pad"><div class="panel-head"><div><h2>${c.name}</h2><p>Sample values are math exercises, not medication orders.</p></div></div><div class="calculator-layout"><div class="calc-fields">${c.unit?`<label><span class="form-label">Dose unit (use the same unit throughout)</span><select id="calc-unit" data-calc="unit"><option ${ui.calcValues.unit==='mg'?'selected':''}>mg</option><option ${ui.calcValues.unit==='mcg'?'selected':''}>mcg</option><option ${ui.calcValues.unit==='units'?'selected':''}>units</option></select></label>`:''}${c.fields.map(([key,label])=>`<label><span class="form-label">${label}${c.unit&&['dose','available','perkg','concentration'].includes(key)?` (${ui.calcValues.unit}${key==='perkg'?'/kg':key==='concentration'?'/mL':''})`:''}</span><input type="number" min="0" step="any" inputmode="decimal" data-calc="${key}" aria-label="${esc(label)}" value="${esc(ui.calcValues[key])}"></label>`).join('')}${ui.calcType==='infusion'?`<label><span class="form-label">Unit of drug amount in bag</span><select data-calc="drugUnit"><option ${ui.calcValues.drugUnit==='mg'?'selected':''}>mg</option><option ${ui.calcValues.drugUnit==='mcg'?'selected':''}>mcg</option></select></label>`:''}</div><div><div class="calc-result" id="calc-result" aria-live="polite"></div><p class="small spaced">${c.description}</p><div class="detail-section"><h3>Before you finish</h3>${list(['Write the units next to every value.','Check that the unwanted units cancel.','Estimate the answer, then independently check the calculation.'])}</div></div></div></section>`;}
function updateCalc(){const el=$('#calc-result');if(!el)return;const r=calculate(ui.calcType,ui.calcValues);el.innerHTML=r.error?`<h3>Check your inputs</h3><p>${esc(r.error)}</p>`:`<span class="eyebrow mint">Calculated result</span><div style="margin-top:10px"><strong>${(r.value<0.001?r.value.toExponential(3):Number(r.value).toLocaleString(undefined,{maximumFractionDigits:3}))}</strong> <span class="mint">${r.unit}</span></div>${r.dose?`<p>Total: ${esc(r.dose)}</p>`:''}<div class="calc-formula">${esc(r.formula)}</div><small style="margin-top:16px">${ui.calcType==='drip'?'Rounded to nearest whole drop.':'Up to 3 decimal places; very small results use scientific notation.'}</small>`;}

function resolveItem(key){const [type,...rest]=key.split(':');const id=rest.join(':');if(type==='drug'){const d=drugs.find(x=>x.id===id);return d?{title:d.name,kind:'Medication',action:'drug',id}:null;}if(type==='guide'){const g=guides.find(x=>x.id===id);return g?{title:g.title,kind:'Study guide',href:'#/guides/'+id}:null;}if(type==='rhythm'){const r=rhythms.find(x=>x.id===id);return r?{title:r.name,kind:'ECG rhythm',action:'open-rhythm',id}:null;}return {title:state.notes[key]?.split('\n')[0]?.slice(0,80)||'Study note',kind:'Personal note'};}
function notebookView(){const bookmarks=state.bookmarks.map(key=>({key,item:resolveItem(key)})).filter(x=>x.item);const notes=Object.entries(state.notes).filter(([,v])=>v.trim());return `<section><div class="section-title"><h2>Saved references</h2><span class="small">${bookmarks.length} saved</span></div>${bookmarks.length?`<div class="grid three">${bookmarks.map(({key,item})=>`<div class="panel note-card"><div class="card-top">${badge(item.kind,'blue')}${saveButton(key)}</div><h3>${esc(item.title)}</h3>${item.href?`<a class="link-button" href="${item.href}">Open reference ${icon('arrow',14)}</a>`:`<button class="link-button" data-action="${item.action}" data-id="${esc(item.id)}">Open reference ${icon('arrow',14)}</button>`}</div>`).join('')}</div>`:empty('Your references, close at hand.','Bookmark a drug card, ECG rhythm, or study guide to save it here.')}</section><section class="spaced"><div class="section-title"><h2>Study notes</h2><span class="small">${notes.length} notes</span></div>${notes.length?`<div class="grid two">${notes.map(([key,value])=>{const item=resolveItem(key);return `<article class="panel note-card"><div class="card-top">${badge(item?.kind||'Study note','lavender')}</div><h3>${esc(item?.title||'Study note')}</h3><div class="note-body">${esc(value)}</div>${button('Edit note','edit-note','small',`data-key="${esc(key)}" data-title="${esc(item?.title||'Study note')}"`)}</article>`;}).join('')}</div>`:empty('Make it stick in your own words.','Add notes from a drug card, a guide, or the New note button.')}</section>`;}
function editNote(key,title){openModal(title||'New study note',`<label><span class="form-label">Your study note</span><textarea id="note-editor" class="note-field" maxlength="20000" style="min-height:230px" placeholder="Key takeaways, memory aids, and questions to review…">${esc(state.notes[key]||'')}</textarea></label><p class="small" style="margin-top:10px">For study notes only. Do not enter real patient information.</p><div class="detail-controls">${button('Save note','save-note','primary',`data-key="${esc(key)}"`)}${state.notes[key]?button('Delete note','delete-note','danger',`data-key="${esc(key)}"`):''}</div>`,'My notebook');setTimeout(()=>$('#note-editor')?.focus(),0);}
function progressView(){const t=totals();const categories=[...new Set(state.history.map(h=>h.category))];return `${statsHTML([[state.history.length,'Completed sessions','check'],[t.total,'Questions & decisions','layers'],[t.total?percent(t.correct,t.total)+'%':'—','First-attempt accuracy','target'],[Object.keys(state.reviews).length,'Flashcards reviewed','book']])}<div class="grid two"><section class="panel panel-pad"><div class="panel-head"><h2>Practice results by topic</h2></div>${categories.length?categories.map(c=>{const h=state.history.filter(x=>x.category===c);const a=h.reduce((v,x)=>({n:v.n+x.correct,d:v.d+x.total}),{n:0,d:0});return `<div class="subject-progress"><span>${esc(c)}</span><div class="progress-track"><div class="progress-fill" style="width:${percent(a.n,a.d)}%"></div></div><small>${a.n}/${a.d} · ${percent(a.n,a.d)}%</small></div>`;}).join(''):'<p>Complete a practice session to start tracking your learning.</p>'}</section><section class="panel panel-pad"><div class="panel-head"><h2>Make this space yours</h2></div><p style="font-size:.875rem">Progress, notes, and saved references live in this browser. Export a backup to move your study data to another device.</p><div class="detail-controls">${button(`${icon('download',16)} Export backup`,'export')}${button(`${icon('upload',16)} Import backup`,'import')}</div><div class="detail-section"><label class="form-label" for="daily-goal">Daily question goal</label><select id="daily-goal">${[5,10,20,30].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} questions / decisions</option>`).join('')}</select><p class="small" style="margin-top:10px">First-attempt accuracy includes questions and scenario decisions. Topic results also include matching attempts and self-reported flashcard recall. These are practice metrics, not measures of clinical competency.</p></div></section></div><section class="panel panel-pad spaced"><div class="panel-head"><h2>Recent sessions</h2><span class="small">Most recent 30</span></div>${state.history.length?`<div class="table-wrap"><table class="activity-table"><thead><tr><th>Activity</th><th>Topic</th><th>Result</th><th>Completed</th></tr></thead><tbody>${[...state.history].reverse().slice(0,30).map(h=>`<tr><td>${esc(h.title)}</td><td>${esc(h.category)}</td><td>${h.correct} / ${h.total}</td><td>${new Date(h.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</td></tr>`).join('')}</tbody></table></div>`:'<p>No completed sessions yet. Your first session will appear here.</p>'}</section>`;}
function sourcesView(){return `<section class="panel panel-pad"><h2>Built for learning</h2><p class="spaced">Pulse is an independent educational study collection for US paramedic students. It is not an official NREMT product, an exhaustive curriculum, a clinical protocol, or a substitute for supervised training. Use your course materials and current local protocols to resolve differences.</p><div class="grid two detail-section"><div><h3>Medication cards</h3><p>Adult doses are separated by indication and route. Pediatric regimens, infusions, and advanced airway medications may require protocol-specific detail. Verify product concentration and maximum dose. No content has undergone independent clinical sign-off.</p></div><div><h3>ECGs & scenarios</h3><p>Strips are simplified teaching illustrations. The simulator follows scripted decisions and vital changes, not a validated physiology model. Clinical outcomes cannot be inferred from the simulated score.</p></div></div><div class="detail-section"><h3>Content dates</h3><p>Sources accessed September 15, 2026. AHA 2025 guidance is included where referenced. Older foundational sources are identified by title. This static site does not automatically refresh clinical guidance.</p></div><div class="detail-section"><h3>Privacy</h3><p>No account is needed. Study data stays in your browser unless you export it. The app does not send notes or scores to a server. Hosting providers may maintain ordinary access logs. Avoid entering patient information.</p></div></section><section class="panel panel-pad spaced"><div class="panel-head"><h2>Reference collection</h2><span class="small">${sources.length} sources</span></div>${sources.map((s,i)=>`<div class="source-item"><span class="source-number">${String(i+1).padStart(2,'0')}</span><div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('link',13)}</a><small>${esc(s.organization)} · Accessed ${esc(s.accessed||'2026-09-15')}</small></div></div>`).join('')}</section>`;}

function searchModal(){openModal('Search your study space',`<label class="search-field" style="display:block">${icon('search',18)}<input id="global-search" placeholder="Drug, rhythm, term, or topic…" aria-label="Search all study content" autocomplete="off"></label><div id="global-results" class="search-results"><p class="small">Search across ${drugs.length} medications, ${rhythms.length} rhythms, ${glossary.length} terms, and ${guides.length} guides.</p></div>`);setTimeout(()=>$('#global-search')?.focus(),0);}
function globalSearch(q){const value=q.trim().toLowerCase();const out=$('#global-results');if(!value){out.innerHTML='<p class="small">Type a term to search your study space.</p>';return;}const found=[...drugs.map(d=>({name:d.name,text:d.name+' '+d.aliases.join(' ')+' '+d.indications.join(' '),type:'Medication',action:'drug',id:d.id})),...rhythms.map(r=>({name:r.name,text:r.name+' '+r.explanation,type:'ECG rhythm',action:'open-rhythm',id:r.id})),...guides.map(g=>({name:g.title,text:g.title+' '+g.summary,type:'Study guide',path:'guides/'+g.id})),...glossary.map(g=>({name:g.term,text:g.term+' '+g.definition,type:'Term',action:'search-term',id:g.term}))].filter(x=>x.text.toLowerCase().includes(value)).slice(0,25);out.innerHTML=found.length?found.map(x=>x.path?`<a class="search-result" href="#/${x.path}"><span>${esc(x.name)}</span><small>${x.type}</small></a>`:`<button class="search-result" data-action="${x.action}" data-id="${esc(x.id)}"><span>${esc(x.name)}</span><small>${x.type}</small></button>`).join(''):'<p class="small">No matching results. Try a broader search term.</p>';}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`pulse-study-backup-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Study backup downloaded.');}
function settings(){openModal('Your study settings',`<label><span class="form-label">Display name (optional)</span><input id="display-name" maxlength="50" value="${esc(state.name)}" placeholder="Your name" style="width:100%"></label><div class="detail-controls">${button('Save settings','save-settings','primary')}${button('Export backup','export')}</div><div class="detail-section"><p class="small">Progress is stored on this device. Export a backup before clearing browser data.</p>${button('Reset all study data','reset-confirm','small danger','style="margin-top:18px"')}</div>`);}

document.addEventListener('click',e=>{if(e.target.closest('#modal a[href^="#"]'))closeModal();if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();return;}const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id,key=el.dataset.key;
 switch(action){
 case 'menu':$('.sidebar').classList.add('open');$('.mobile-shade').classList.add('visible');$('.mobile-toggle').setAttribute('aria-expanded','true');break;
 case 'menu-close':$('.sidebar').classList.remove('open');$('.mobile-shade').classList.remove('visible');$('.mobile-toggle').setAttribute('aria-expanded','false');break;
 case 'theme':state.theme=state.theme==='dark'?'light':'dark';save();render();break;
 case 'search':searchModal();break;case 'close-modal':closeModal();break;
 case 'drug':drugModal(id);break;
 case 'bookmark':{const i=state.bookmarks.indexOf(key);if(i<0)state.bookmarks.push(key);else state.bookmarks.splice(i,1);save();el.classList.toggle('saved',i<0);el.setAttribute('aria-pressed',String(i<0));if(el.classList.contains('button'))el.innerHTML=`${icon('bookmark',16)} ${i<0?'Bookmarked':'Bookmark'}`;toast(i<0?'Reference saved to your notebook.':'Bookmark removed.');if(!$('#modal').open)render();break;}
 case 'drug-saved':ui.drugSaved=!ui.drugSaved;render();break;
 case 'drug-flash':startFlash('drugs','all');break;
 case 'rhythm':ui.ecgId=id;render();break;
 case 'rhythm-challenge':ui.ecgId=id;ui.ecgHidden=true;go('ecg');break;
 case 'open-rhythm':closeModal();ui.ecgId=id;ui.ecgHidden=false;go('ecg');break;
 case 'ecg-hide':ui.ecgHidden=!ui.ecgHidden;render();break;
 case 'ecg-quiz':newQuiz('ecg','ECG recognition',10);break;
 case 'quick-quiz':newQuiz();break;
 case 'term-practice':ui.practiceTab='terminology';ui.quiz=null;ui.match=null;ui.flash=null;go('practice');break;
 case 'practice-tab':ui.practiceTab=el.dataset.tab;ui.quiz=null;ui.match=null;ui.flash=null;render();break;
 case 'start-practice':if(ui.practiceTab==='matching')startMatch();else if(ui.practiceTab==='flashcards')startFlash($('#flash-deck').value,$('#flash-filter').value);else newQuiz(ui.practiceTab,$('#quiz-category')?.value||'Mixed',+($('#quiz-count')?.value||10));break;
 case 'quiz-answer':{const q=ui.quiz;if(!q||q.selected!==null||q.finished)break;q.selected=+el.dataset.index;q.responses.push({selected:q.selected,correct:q.selected===q.items[q.index].answer});markDay();render();break;}
 case 'quiz-next':{const q=ui.quiz;if(!q||q.selected===null||q.finished)break;if(q.index+1>=q.items.length){q.finished=true;record(q.mode==='terminology'?'terminology':'quiz',q.mode==='ecg'?'Rhythm recognition':q.mode==='terminology'?'Terminology sprint':'Clinical practice',q.responses.filter(x=>x.correct).length,q.items.length,q.category);}else{q.index++;q.selected=null;}render();break;}
 case 'retry-missed':{const q=ui.quiz;const items=q.items.filter((_,i)=>!q.responses[i].correct);ui.quiz={...q,items:shuffle(items),index:0,selected:null,responses:[],finished:false};render();break;}
 case 'end-practice':ui.quiz=null;ui.flash=null;ui.match=null;render();break;
 case 'new-match':startMatch();break;
 case 'match-left':if(ui.match&&!ui.match.matched.includes(id)){ui.match.selected=id;ui.match.wrong=null;render();}break;
 case 'match-right':{const m=ui.match;if(!m||m.completed||m.matched.includes(id))break;if(!m.selected){toast('Select a term first.');break;}m.attempts++;if(m.selected===id){m.matched.push(id);m.selected=null;m.wrong=null;markDay();if(m.matched.length===m.items.length){m.completed=true;record('matching','Match pairs',6,m.attempts,'Terminology');}else toast('That’s a match.');}else{m.wrong=id;toast('Not quite. Try another definition.');}render();break;}
 case 'flash-flip':if(ui.flash&&!ui.flash.finished){ui.flash.revealed=!ui.flash.revealed;render();}break;
 case 'flash-rate':{const f=ui.flash;if(!f||!f.revealed||f.finished)break;const c=f.items[f.index],rating=el.dataset.rating,old=state.reviews[c.id]?.interval||0;const interval=rating==='again'?0:rating==='good'?Math.max(1,Math.min(365,old*2)):Math.max(4,Math.min(365,old*3));state.reviews[c.id]={interval,due:Date.now()+interval*86400000};f.ratings.push(rating);markDay();if(f.index+1>=f.items.length){f.finished=true;record('flashcards','Flashcard review',f.ratings.filter(x=>x!=='again').length,f.items.length,f.deck==='terms'?'Terminology':'Pharmacology');}else{f.index++;f.revealed=false;}render();break;}
 case 'start-case':closeModal();startCase(id);break;
 case 'confirm-leave':openModal('Leave this scenario?',`<p>The current unfinished attempt will be discarded. Completed sessions stay in your progress.</p><div class="detail-controls">${button('Keep studying','close-modal','primary')}${button('Leave scenario','leave-case','ghost')}</div>`);break;
 case 'leave-case':closeModal();ui.caseRun=null;render();break;
 case 'case-answer':{const r=ui.caseRun;if(!r||r.selected!==null||r.finished)break;const i=+el.dataset.index,o=r.case.steps[r.index].options[i];r.selected=i;r.attempts++;if(o.correct&&r.attempts===1)r.score++;if(o.effect)Object.assign(r.vitals,o.effect);r.log.push({stage:r.index+1,label:o.label,correct:o.correct});markDay();render();break;}
 case 'case-retry':{const r=ui.caseRun;if(!r||r.selected===null||r.case.steps[r.index].options[r.selected].correct)break;r.selected=null;r.vitals={...r.baseline};render();break;}
 case 'case-next':{const r=ui.caseRun;if(!r||r.selected===null||!r.case.steps[r.index].options[r.selected].correct||r.finished)break;if(r.index+1>=r.case.steps.length){r.finished=true;record('simulator',r.case.title,r.score,r.case.steps.length,r.case.category);}else{r.index++;r.selected=null;r.attempts=0;Object.assign(r.vitals,r.case.steps[r.index].onEnter||{});r.baseline={...r.vitals};}render();break;}
 case 'calc-type':ui.calcType=el.dataset.type;ui.calcValues=calcDefaults(ui.calcType);render();break;
 case 'edit-note':editNote(key,el.dataset.title);break;
 case 'new-note':editNote('note:'+Date.now(),'New study note');break;
 case 'save-note':{const text=$('#note-editor').value.trim();if(text)state.notes[key]=text;else delete state.notes[key];save();closeModal();render();toast(text?'Study note saved.':'Empty note removed.');break;}
 case 'delete-note':openModal('Delete this study note?',`<p>This removes the note from this device.</p><div class="detail-controls">${button('Keep note','close-modal','primary')}${button('Delete note','delete-note-final','danger',`data-key="${esc(key)}"`)}</div>`);break;
 case 'delete-note-final':delete state.notes[key];save();closeModal();render();toast('Note deleted.');break;
 case 'search-term':closeModal();ui.glossaryQuery=id;go('glossary');break;
 case 'print':window.print();break;
 case 'export':exportData();break;
 case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>5000000)throw new Error('Choose a backup smaller than 5 MB.');const raw=JSON.parse(await file.text());if(raw.version!==1||!Array.isArray(raw.history)||!Array.isArray(raw.bookmarks))throw new Error('This file is not a Pulse study backup.');const imported=sanitizeState(raw);openModal('Import this study backup?',`<p>This will replace the study data on this device with ${imported.history.length} sessions, ${imported.bookmarks.length} bookmarks, and ${Object.keys(imported.notes).length} notes.</p><div class="detail-controls">${button('Cancel','close-modal')}${button('Export current data','export')}${button('Replace with backup','import-confirm','primary')}</div>`);ui.pendingImport=imported;}catch(err){toast(err.message||'Could not read that backup.');}};input.click();break;}
 case 'import-confirm':if(ui.pendingImport){state=ui.pendingImport;delete ui.pendingImport;ui.quiz=null;ui.flash=null;ui.match=null;ui.caseRun=null;save();closeModal();render();toast('Study backup imported.');}break;
 case 'settings':settings();break;
 case 'save-settings':state.name=$('#display-name').value.trim();save();closeModal();render();toast('Settings saved.');break;
 case 'reset-confirm':openModal('Reset all study data?',`<p>This deletes notes, bookmarks, review schedules, and progress from this browser. Export a backup first if you want to keep them.</p><div class="detail-controls">${button('Keep my data','close-modal','primary')}${button('Export backup','export')}${button('Reset everything','reset-final','danger')}</div>`);break;
 case 'reset-final':state=defaults();save();ui.quiz=null;ui.flash=null;ui.match=null;ui.caseRun=null;closeModal();render();toast('Study data reset.');break;
 }
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='drug-search'){ui.drugQuery=el.value;$('#drug-results').innerHTML=drugResults();}if(el.id==='guide-search'){ui.guideQuery=el.value;$('#guide-results').innerHTML=guideResults();}if(el.id==='glossary-search'){ui.glossaryQuery=el.value;$('#glossary-results').innerHTML=glossaryResults();}if(el.id==='global-search')globalSearch(el.value);if(el.dataset.calc){ui.calcValues[el.dataset.calc]=el.value;updateCalc();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='drug-category'){ui.drugCategory=el.value;$('#drug-results').innerHTML=drugResults();}if(el.id==='ecg-annotations'){ui.annotations=el.checked;render();}if(el.id==='daily-goal'){state.goal=+el.value;save();toast('Daily goal updated.');}if(el.id==='calc-unit'){ui.calcValues.unit=el.value;render();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();}if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.mobile-shade')?.classList.remove('visible');$('.mobile-toggle')?.setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);$('#main h1')?.focus({preventScroll:true});});
render();
const modelContext=document.modelContext;if(modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'search_study_content',title:'Search study references',description:'Find drug cards, ECG lessons, terminology, and study guides without changing study progress.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input.query!=='string'||!input.query.trim()||input.query.length>200)throw new Error('Provide a search query from 1 to 200 characters.');const q=input.query.toLowerCase();return [...drugs.map(d=>({id:d.id,name:d.name,type:'drug'})),...rhythms.map(r=>({id:r.id,name:r.name,type:'rhythm'})),...glossary.map(g=>({id:g.id,name:g.term,type:'term'})),...guides.map(g=>({id:g.id,name:g.title,type:'guide'}))].filter(x=>x.name.toLowerCase().includes(q)).slice(0,25);}},{name:'open_study_section',title:'Open a study tool',description:'Navigate to a study section. Does not answer questions or complete a session.',inputSchema:{type:'object',properties:{section:{type:'string',enum:navItems.map(x=>x[0])}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!navItems.some(x=>x[0]===input.section))throw new Error('Choose a valid study section.');go(input.section);await new Promise(resolve=>setTimeout(resolve,0));return {section:route().page};}}]){try{Promise.resolve(modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}}
